<template>
  <div class="page">
    <div class="crumb"><button @click="router.back()">返回作业</button><span>/</span><strong>{{ detail?.title || '作业详情' }}</strong></div>
    <div v-if="errorMessage" class="error">{{ errorMessage }}</div>
    <section v-if="detail" class="panel">
      <header><div><p>ASSIGNMENT DETAIL</p><h1>{{ detail.title }}</h1><span>截止时间：{{ formatDate(detail.deadline) }}</span></div><b class="status">{{ formation ? '组队中' : reviewed ? '已批阅' : '小组已锁定' }}</b></header>
      <div class="content">
        <div class="top-sections">
          <section class="plain-section"><h2>作业要求</h2><p>{{ detail.description || '暂无详细作业说明' }}</p></section>
          <section v-if="graded" class="grade-panel"><h2>我的成绩</h2><p v-if="!reviewed" class="unpublished-note">教师还未发布该作业成绩</p><div v-else class="grades"><div><small>个人成绩</small><strong>{{ score(currentScore?.finalScore) }}</strong></div><div><small>团队成绩</small><strong>{{ score(currentScore?.groupScore) }}</strong></div><button class="appeal" @click="appealVisible=true">我要申诉</button></div></section>
        </div>
        <section v-if="detail.parts?.length" class="plain-section"><h2>评价分支</h2><div v-for="part in detail.parts" :key="part.id" class="part"><span>{{ part.name }}</span><b>{{ Number(part.weight * 100).toFixed(0) }}%</b><small>{{ part.description || '暂无说明' }}</small></div></section>
        <section><h2>我的小组</h2><div v-if="detail.groupName" class="team"><strong>{{ detail.groupName }}</strong><label v-for="member in detail.members" :key="member.studentId"><span>{{ member.name }}（{{ member.studentNo }}）</span><input v-if="!reviewed" v-model.number="contributionScores[member.studentId]" type="number" min="0" max="100" step="0.1" placeholder="贡献占比 %"><span v-else class="contribution-readonly">贡献占比：{{ member.contributionRatio == null ? '—' : Number(member.contributionRatio).toFixed(1) + '%' }}</span></label></div><el-empty v-else description="暂未加入小组" /></section>
        <section v-if="reviewed" class="readonly"><h2>作业提交内容</h2><p>{{ detail.content || '本次提交使用附件或暂无正文内容' }}</p><div v-if="detail.attachments?.length" class="student-attachments"><a v-for="file in detail.attachments" :key="file.id" :href="`/api/v1/files?key=${encodeURIComponent(file.storageKey)}`" target="_blank" rel="noreferrer">{{ file.originalName }}</a></div></section><StudentSubmissionPanel v-else :assignment-id="route.params.assignmentId" :contribution-scores="contributionScores" :initial-content="detail.content" :initial-note="detail.submitNote" @submitted="load" />
      </div>
    </section><div v-else class="loading">正在加载…</div>
    <div v-if="appealVisible" class="dialog"><div class="dialog-card"><h2>提交成绩申诉</h2><textarea v-model="appealReason" placeholder="请填写申诉理由" /><button class="secondary" @click="appealVisible=false">取消</button><button class="primary" :disabled="!appealReason.trim()" @click="submitAppeal">提交申诉</button></div></div>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import StudentSubmissionPanel from '@/components/student/StudentSubmissionPanel.vue'
import { getAssignment, getScores, appealScore } from '@/api/student'
import { getErrorMessage } from '@/api/response'
import { saveRecentProject } from '@/utils/studentRecentProject'
const route=useRoute(),router=useRouter(),detail=ref(null),scores=ref([]),contributionScores=ref({}),errorMessage=ref(''),appealVisible=ref(false),appealReason=ref('')
const formation=computed(()=>detail.value?.teamFormation===true||detail.value?.teamFormation===1),reviewed=computed(()=>detail.value?.scorePublished===true||detail.value?.scorePublished===1),graded=computed(()=>reviewed.value||detail.value?.teacherScore!=null||['GRADED','SCORED','REVIEWED'].includes(detail.value?.submissionStatus)),currentScore=computed(()=>scores.value.find(item=>Number(item.assignmentId)===Number(route.params.assignmentId)))
const score=v=>v==null?'—':Number(v).toFixed(2),formatDate=v=>v?new Date(v).toLocaleString('zh-CN'):'未设置'
const load=async()=>{detail.value=await getAssignment(route.params.assignmentId);saveRecentProject({assignmentId:route.params.assignmentId,courseId:detail.value.courseId,title:detail.value.title,courseName:detail.value.courseName,deadline:detail.value.deadline});scores.value=await getScores();detail.value.members?.forEach(m=>{if(!(m.studentId in contributionScores.value))contributionScores.value[m.studentId]=null})}
const submitAppeal=async()=>{try{await appealScore(currentScore.value.scoreResultId,{reason:appealReason.value});appealVisible.value=false;ElMessage.success('申诉已提交')}catch(e){errorMessage.value=getErrorMessage(e,'申诉提交失败')}}
onMounted(()=>load().catch(e=>errorMessage.value=getErrorMessage(e,'作业详情加载失败')))
</script>
<style scoped>
.page{max-width:1040px;margin:0 auto}.crumb{display:flex;align-items:center;gap:8px;margin-bottom:20px;color:#8795a6;font-size:13px}.crumb button{padding:0;border:0;background:none;color:#4f86c6;cursor:pointer}.panel{overflow:hidden;border:1px solid #e3eaf2;border-radius:14px;background:#fff;box-shadow:0 6px 20px rgba(38,59,83,.07)}header{display:flex;justify-content:space-between;gap:20px;padding:27px 28px;border-bottom:1px solid #e9eef5;background:linear-gradient(120deg,#fff 50%,#f1f6fd)}header p{margin:0;color:#4f86c6;letter-spacing:1.5px;font-size:11px;font-weight:700}h1{margin:8px 0;color:#263b53;font-size:27px}header span{color:#7c8da0;font-size:13px}.status{padding:6px 13px;height:max-content;border-radius:99px;color:#356798;background:#eaf2fa;font-size:12px;white-space:nowrap}.content{display:grid;gap:22px;padding:27px 28px}.content>section,.top-sections{margin:0}.content>section:not(.readonly),.top-sections{padding-bottom:22px;border-bottom:1px solid #edf1f5}.top-sections{display:flex;flex-direction:column;gap:18px}.plain-section,.grade-panel{padding:0;border:0;background:transparent}.plain-section h2,.grade-panel h2,.content>section h2{margin:0 0 12px;color:#334155;font-size:17px}.plain-section p,.readonly p{margin:0;color:#64748b;line-height:1.8}.unpublished-note{padding:13px 15px;border-radius:8px;background:#f6f8fb}.grades{display:flex;align-items:center;gap:38px;padding:17px 19px;border-radius:11px;background:#f6f9fd}.grades div{display:flex;align-items:baseline;gap:10px}.grades small{color:#52657a;font-size:14px;font-weight:600}.grades strong{color:#356798;font-size:29px;font-weight:700}.appeal{margin-left:auto;padding:9px 15px;border:0;border-radius:7px;color:#fff;background:#d78842;cursor:pointer}.part{display:grid;grid-template-columns:1fr auto;gap:5px;padding:12px 0;border-bottom:1px solid #edf1f4}.part:last-child{border-bottom:0}.part b{color:#356798}.part small{grid-column:1/-1;color:#98a5b3}.team{display:flex;flex-direction:column;gap:8px}.team strong,.team label{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:10px 13px;border-radius:8px;background:#f5f8fb;color:#52657a}.team strong{color:#356798;background:#eaf2fa}.team input{width:130px;padding:8px 10px;border:1px solid #dbe3ea;border-radius:7px;outline:none}.team input:focus{border-color:#6b9ed8;box-shadow:0 0 0 3px rgba(107,158,216,.12)}.contribution-readonly{color:#52657a;font-size:13px}.readonly{margin-top:0}.student-attachments{display:grid;gap:8px;margin-top:14px}.student-attachments a{padding:9px 12px;border-radius:7px;color:#356798;background:#f3f7fb;text-decoration:none}.student-attachments a:hover{background:#eaf2fa}.error{margin-bottom:16px;padding:12px;border-radius:8px;color:#b42318;background:#fff5f5}.loading{text-align:center;padding:40px;color:#8795a6}.dialog{position:fixed;z-index:50;inset:0;display:grid;place-items:center;padding:20px;background:rgba(38,59,83,.34);backdrop-filter:blur(2px)}.dialog-card{width:min(420px,100%);padding:24px;border-radius:12px;background:#fff;box-shadow:0 24px 60px rgba(15,23,42,.2)}.dialog-card h2{margin-top:0;color:#334155}.dialog-card textarea{width:100%;min-height:120px;margin:12px 0;padding:10px;box-sizing:border-box;border:1px solid #dbe3ea;border-radius:7px;resize:vertical}.primary,.secondary{padding:10px 17px;border:0;border-radius:7px;cursor:pointer}.primary{margin-left:8px;color:#fff;background:#356798}.secondary{color:#356798;background:#eaf2fa}@media(max-width:700px){header,.content{padding:20px}.grades{align-items:flex-start;flex-direction:column;gap:12px}.appeal{margin-left:0}.team label{align-items:stretch;flex-direction:column}.team input{width:100%;box-sizing:border-box}}
</style>


